function Home() {
  const { isAuthenticated } = useAuth();
  return <div className="min-h-screen bg-[#f7f8fb] text-[#172033]">
    <div className="absolute inset-x-0 top-0 h-[560px] overflow-hidden pointer-events-none"><div className="hero-grid absolute inset-0 opacity-70" /><div className="absolute left-[53%] top-[-180px] h-[520px] w-[520px] rounded-full bg-[#dff4f0] blur-3xl opacity-70" /></div>
    <header className="relative z-10 mx-auto flex max-w-7xl items-center justify-between px-5 py-6 lg:px-8"><Brand light /><div className="hidden items-center gap-8 text-sm font-medium text-[#677187] md:flex"><a href="#how-it-works" className="hover:text-[#172033]">How it works</a><a href="#features" className="hover:text-[#172033]">Features</a><Link href="/lectures" className="hover:text-[#172033]">Demo lecture</Link></div><div className="flex items-center gap-3"><button className="hidden rounded-xl px-3 py-2 text-sm font-semibold text-[#566078] hover:bg-white md:block" onClick={() => startLogin()}>Sign in</button><button className="rounded-xl bg-[#172033] px-4 py-2.5 text-sm font-semibold text-white shadow-lg shadow-[#172033]/15 transition hover:-translate-y-0.5" onClick={() => isAuthenticated ? window.location.assign("/dashboard") : startLogin()}>Get started <ArrowUpRight className="ml-1 inline h-4 w-4" /></button></div></header>
    <main className="relative z-10 mx-auto max-w-7xl px-5 pb-20 pt-14 lg:px-8 lg:pt-24"><section className="grid items-center gap-16 lg:grid-cols-[1.05fr_.95fr]"><div><div className="mb-6 inline-flex items-center gap-2 rounded-full border border-[#cfe7e3] bg-[#effaf8] px-3 py-1.5 text-xs font-bold uppercase tracking-[.16em] text-[#137a70]"><span className="h-2 w-2 rounded-full bg-[#24a99a]" /> Academic memory, upgraded</div><h1 className="max-w-3xl text-5xl font-semibold leading-[1.03] tracking-[-.055em] text-[#172033] sm:text-6xl lg:text-[78px]">Your lectures.<br /><span className="text-[#23a495]">Remembered by AI.</span></h1><p className="mt-7 max-w-xl text-lg leading-8 text-[#677187]">LectureAI turns recordings into searchable knowledge, practical study notes, and a focused assistant that only answers from what your professor actually said.</p><div className="mt-9 flex flex-wrap items-center gap-3"><button onClick={() => isAuthenticated ? window.location.assign("/upload") : startLogin()} className="rounded-2xl bg-[#172033] px-5 py-3.5 text-sm font-semibold text-white shadow-xl shadow-[#172033]/15 transition hover:-translate-y-0.5">Upload your first lecture <UploadCloud className="ml-2 inline h-4 w-4" /></button><Link href="/lectures/demo-trees-and-graphs" className="rounded-2xl border border-[#dce1e9] bg-white px-5 py-3.5 text-sm font-semibold text-[#172033] shadow-sm transition hover:-translate-y-0.5">Explore demo lecture <Play className="ml-2 inline h-4 w-4 fill-current" /></Link></div><div className="mt-9 flex items-center gap-5 text-sm text-[#7d879a]"><div className="flex -space-x-2"><span className="avatar bg-[#f5c7a5]">MC</span><span className="avatar bg-[#b9d9f0]">AR</span><span className="avatar bg-[#d5c8f5]">SK</span></div><span>Built for the way students actually study.</span></div></div><HeroProductPreview /></section>
    <section id="how-it-works" className="mt-32 border-t border-[#e3e7ee] pt-16"><SectionEyebrow>How it works</SectionEyebrow><div className="mt-5 flex flex-col justify-between gap-10 md:flex-row"><div><h2 className="max-w-xl text-3xl font-semibold tracking-[-.04em] text-[#172033] sm:text-4xl">From lecture noise to a clear next step.</h2></div><p className="max-w-sm text-sm leading-7 text-[#7d879a]">No more scrubbing through recordings or guessing where that one important detail was mentioned.</p></div><div className="mt-12 grid gap-4 md:grid-cols-3">{[["01","Upload lecture","Drop in an audio or video file. Add the context you already know."],["02","AI understands it","Transcription, topics, assignments, announcements, and timeline in one pass."],["03","Ask anything","Search the memory or ask a grounded question with timestamped sources."]].map(([n,t,d]) => <div key={n} className="rounded-3xl border border-[#e2e6ee] bg-white p-6 shadow-sm"><span className="text-xs font-bold tracking-[.18em] text-[#23a495]">{n}</span><h3 className="mt-8 text-xl font-semibold text-[#172033]">{t}</h3><p className="mt-3 text-sm leading-6 text-[#7d879a]">{d}</p><div className="mt-8 h-1 w-14 rounded-full bg-[#c8eee8]" /></div>)}</div></section>
    <section id="features" className="mt-28"><SectionEyebrow>Built for recall</SectionEyebrow><div className="mt-5 grid gap-4 lg:grid-cols-3">{[[Bot,"AI lecture chat","Get concise answers with sources from the lecture."],[FileText,"Smart summary","A useful overview you can revisit before class or exams."],[Check,"Assignment detection","Homework and follow-ups extracted automatically."],[Clock3,"Lecture timeline","Jump directly to the moment a concept was explained."],[CalendarDays,"Important announcements","Deadlines and class instructions stay visible."],[Search,"Searchable memory","Find “AVL” across every lecture you have uploaded."]].map(([Icon,title,desc]) => <div key={title as string} className="rounded-3xl border border-[#e2e6ee] bg-white p-6 shadow-sm transition hover:-translate-y-1 hover:shadow-md"><div className="icon-tile"><Icon className="h-5 w-5" /></div><h3 className="mt-5 font-semibold text-[#172033]">{title as string}</h3><p className="mt-2 text-sm leading-6 text-[#7d879a]">{desc as string}</p></div>)}</div></section>
    <section className="mt-28 overflow-hidden rounded-[32px] bg-[#172033] p-7 text-white sm:p-12"><div className="grid items-end gap-12 lg:grid-cols-[.8fr_1.2fr]"><div><SectionEyebrow light>Try the memory</SectionEyebrow><h2 className="mt-5 text-3xl font-semibold tracking-[-.04em] sm:text-4xl">See a lecture become a study system.</h2><p className="mt-5 max-w-md text-sm leading-7 text-[#aeb8c9]">Our interactive demo shows the exact experience you get after a lecture is processed.</p><Link href="/lectures/demo-trees-and-graphs" className="mt-8 inline-flex items-center rounded-xl bg-[#23a495] px-4 py-3 text-sm font-semibold text-white">Open demo lecture <ChevronRight className="ml-2 h-4 w-4" /></Link></div><div className="rounded-3xl border border-white/10 bg-white/[.06] p-5"><div className="flex items-center justify-between border-b border-white/10 pb-4"><div><p className="text-xs text-[#aeb8c9]">DEMO LECTURE</p><p className="mt-1 font-semibold">Trees &amp; Graphs</p></div><span className="rounded-full bg-[#c6f1e9]/10 px-2.5 py-1 text-xs font-semibold text-[#8ce0d4]">Processed</span></div><div className="grid gap-3 py-5 sm:grid-cols-2"><div className="rounded-2xl bg-white/[.07] p-4"><p className="text-xs text-[#aeb8c9]">Summary</p><p className="mt-3 text-sm leading-6 text-white/90">BST ordering, deletion cases, and AVL rotations.</p></div><div className="rounded-2xl bg-white/[.07] p-4"><p className="text-xs text-[#aeb8c9]">Detected assignment</p><p className="mt-3 text-sm leading-6 text-white/90">Implement insertion and deletion with tests.</p></div></div><div className="flex items-center gap-3 rounded-2xl border border-[#23a495]/30 bg-[#23a495]/10 p-4"><Bot className="h-5 w-5 text-[#7be0d2]" /><p className="text-sm text-white/90">“When did the professor explain deletion?”</p><span className="ml-auto text-xs font-semibold text-[#7be0d2]">15:31</span></div></div></div></section></main><footer className="mx-auto flex max-w-7xl flex-col gap-4 border-t border-[#e3e7ee] px-5 py-8 text-sm text-[#7d879a] sm:flex-row sm:items-center sm:justify-between lg:px-8"><Brand light small /><span>LectureAI · Your academic memory.</span></footer>
  </div>;
}

function HeroProductPreview() { return <div className="relative mx-auto w-full max-w-[560px]"><div className="absolute -right-8 -top-8 h-28 w-28 rounded-full border border-[#cbece7] bg-[#effaf8]" /><div className="relative rounded-[30px] border border-[#e2e6ee] bg-white p-4 shadow-2xl shadow-[#1a2a3d]/10 sm:p-5"><div className="flex items-center justify-between border-b border-[#edf0f4] px-2 pb-4"><div className="flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-full bg-[#efb47d]" /><span className="h-2.5 w-2.5 rounded-full bg-[#f2db78]" /><span className="h-2.5 w-2.5 rounded-full bg-[#80d7c5]" /></div><span className="text-[11px] font-semibold text-[#98a1b1]">lectureai.app</span></div><div className="grid gap-4 py-4 sm:grid-cols-[.75fr_1.25fr]"><div className="rounded-2xl bg-[#f7f8fb] p-3"><Brand small light /><p className="mt-8 text-[10px] font-bold uppercase tracking-[.14em] text-[#9aa3b3]">Your memory</p>{["Overview","My lectures","Search memory","Assignments"].map((x,i)=><div key={x} className={`mt-3 rounded-xl px-3 py-2 text-[11px] font-semibold ${i===0?"bg-white text-[#172033] shadow-sm":"text-[#8993a5]"}`}>{x}</div>)}</div><div><div className="flex items-start justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.14em] text-[#23a495]">Good afternoon</p><p className="mt-1 text-xl font-semibold tracking-[-.03em] text-[#172033]">Your academic memory</p></div><span className="avatar bg-[#d7c8f5]">AR</span></div><div className="mt-5 grid grid-cols-3 gap-2">{[["12","Lectures"],["8h 32m","Listened"],["24","Assignments"]].map(([a,b])=><div key={b} className="rounded-xl border border-[#edf0f4] p-3"><p className="text-base font-semibold text-[#172033]">{a}</p><p className="mt-1 text-[9px] text-[#98a1b1]">{b}</p></div>)}</div><div className="mt-3 rounded-2xl border border-[#edf0f4] p-3"><div className="flex items-center justify-between"><p className="text-[11px] font-semibold text-[#172033]">Recent lectures</p><span className="text-[10px] text-[#23a495]">View all</span></div>{[["Data Structures","Processed","#d4f1ed"],["DBMS","Processed","#e8e0fb"],["Computer Networks","Processing","#fff0d7"]].map(([a,b,c])=><div key={a} className="mt-3 flex items-center gap-2"><span className="h-7 w-7 rounded-lg" style={{background:c}} /><div className="min-w-0 flex-1"><p className="truncate text-[10px] font-semibold text-[#273148]">{a}</p><p className="text-[9px] text-[#98a1b1]">Yesterday · {b}</p></div><ChevronRight className="h-3 w-3 text-[#b5bcc8]" /></div>)}</div></div></div></div></div> }
function Brand({ small=false, light=false }: { small?: boolean; light?: boolean }) { return <Link href="/" className={`flex items-center gap-2 font-bold tracking-[-.04em] ${small?"text-base":"text-lg"} ${light?"text-[#172033]":"text-white"}`}><span className="grid h-8 w-8 place-items-center rounded-xl bg-[#23a495] text-white"><GraduationCap className="h-4 w-4" /></span>Lecture<span className="text-[#23a495]">AI</span></Link> }
function SectionEyebrow({children, light=false}: {children: React.ReactNode; light?: boolean}) { return <p className={`text-xs font-bold uppercase tracking-[.18em] ${light?"text-[#7be0d2]":"text-[#23a495]"}`}>{children}</p> }

function AppShell() {
  const { user, logout, isAuthenticated, loading } = useAuth();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [location] = useLocation();
  const isDemo = !isAuthenticated;
  const updateProfile = trpc.auth.updateProfile.useMutation();
  useEffect(() => {
    if (!isAuthenticated || !user || updateProfile.isPending) return;
    const pending = sessionStorage.getItem("lectureai-registration-profile");
    if (!pending) return;
    try {
      const profile = JSON.parse(pending) as { name?: string; email?: string };
      if (profile.name && profile.email) updateProfile.mutate({ name: profile.name, email: profile.email });
      sessionStorage.removeItem("lectureai-registration-profile");
    } catch {
      sessionStorage.removeItem("lectureai-registration-profile");
    }
  }, [isAuthenticated, user, updateProfile]);
  return <div className="min-h-screen bg-[#f7f8fb] text-[#172033]"><aside className={`fixed inset-y-0 left-0 z-40 w-64 border-r border-[#e6eaf0] bg-white p-5 transition-transform lg:translate-x-0 ${mobileOpen?"translate-x-0":"-translate-x-full"}`}><div className="flex items-center justify-between"><Brand light /><button className="lg:hidden" onClick={()=>setMobileOpen(false)}><X className="h-5 w-5 text-[#8c96a7]" /></button></div><div className="mt-10 rounded-2xl bg-[#effaf8] p-4"><p className="text-[10px] font-bold uppercase tracking-[.15em] text-[#23a495]">{isDemo?"Demo mode":"Your workspace"}</p><p className="mt-2 text-sm font-semibold text-[#172033]">{isDemo?"Explore the sample lecture":"Keep building your memory"}</p><p className="mt-1 text-xs leading-5 text-[#7d879a]">{isDemo?"Sample data is clearly marked and never mixed with uploads.":"Upload a lecture to start processing."}</p></div><nav className="mt-8 space-y-1">{nav.map(({href,label,icon:Icon})=><Link key={href} href={href} onClick={()=>setMobileOpen(false)} className={`flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold transition ${location===href?"bg-[#172033] text-white shadow-md shadow-[#172033]/10":"text-[#778196] hover:bg-[#f3f5f8] hover:text-[#172033]"}`}><Icon className="h-4 w-4" />{label}</Link>)}</nav><div className="mt-8 border-t border-[#edf0f4] pt-5"><Link href="/settings" className={`flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold ${location==="/settings"?"bg-[#f0f3f7] text-[#172033]":"text-[#778196] hover:bg-[#f3f5f8]"}`}><Settings className="h-4 w-4" />Settings</Link>{isAuthenticated?<button onClick={()=>logout()} className="mt-1 flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-[#778196] hover:bg-[#fff1f0] hover:text-[#c15b55]"><LogOut className="h-4 w-4" />Log out</button>:<button onClick={()=>startLogin()} className="mt-1 flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-[#778196] hover:bg-[#f3f5f8]"><ArrowUpRight className="h-4 w-4" />Sign in</button>}</div><div className="absolute bottom-5 left-5 right-5 rounded-2xl bg-[#172033] p-4 text-white"><div className="flex items-center gap-2"><Sparkles className="h-4 w-4 text-[#7be0d2]" /><p className="text-xs font-semibold">Study smarter</p></div><p className="mt-2 text-[11px] leading-5 text-[#aeb8c9]">Ask about any moment in your lectures.</p></div></aside><div className={`fixed inset-0 z-30 bg-[#172033]/30 lg:hidden ${mobileOpen?"block":"hidden"}`} onClick={()=>setMobileOpen(false)} /><div className="lg:pl-64"><header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-[#e6eaf0] bg-[#f7f8fb]/90 px-5 backdrop-blur lg:px-8"><div className="flex items-center gap-3"><button className="rounded-xl p-2 hover:bg-white lg:hidden" onClick={()=>setMobileOpen(true)}><Menu className="h-5 w-5" /></button><div className="hidden items-center gap-2 text-sm text-[#8a94a6] sm:flex"><span>Workspace</span><ChevronRight className="h-4 w-4" /><span className="font-semibold text-[#172033]">{location==="/dashboard"?"Overview":location.slice(1).split("/")[0] || "Overview"}</span></div></div><div className="flex items-center gap-3"><Link href="/search" className="hidden rounded-xl border border-[#e2e6ee] bg-white p-2.5 text-[#7c8799] shadow-sm sm:block"><Search className="h-4 w-4" /></Link><button onClick={()=>isAuthenticated?window.location.assign("/upload"):startLogin()} className="rounded-xl bg-[#172033] px-3.5 py-2.5 text-xs font-semibold text-white shadow-md shadow-[#172033]/10"><Plus className="mr-1 inline h-4 w-4" />New lecture</button>{user?<span className="avatar bg-[#d7c8f5]">{(user.name??"AR").slice(0,2).toUpperCase()}</span>:<button onClick={()=>startLogin()} className="hidden text-xs font-semibold text-[#677187] sm:block">Sign in</button>}</div></header><main className="mx-auto max-w-7xl px-5 py-8 lg:px-8"><Switch><Route path="/dashboard" component={DashboardPage} /><Route path="/lectures" component={LecturesPage} /><Route path="/lectures/:id" component={LectureDetailPage} /><Route path="/upload" component={UploadPage} /><Route path="/search" component={SearchPage} /><Route path="/assignments" component={AssignmentsPage} /><Route path="/settings" component={SettingsPage} /><Route component={DashboardPage} /></Switch></main></div></div>;
}

function DashboardPage() { const { data, isLoading } = trpc.lectures.list.useQuery(); const lectures = data?.lectures ?? []; return <div className="space-y-8"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><SectionEyebrow>{data?.isDemoMode?"Demo workspace":"Personal workspace"}</SectionEyebrow><h1 className="mt-2 text-3xl font-semibold tracking-[-.045em] sm:text-4xl">Good afternoon<span className="text-[#23a495]">.</span></h1><p className="mt-2 text-sm text-[#7d879a]">Your academic memory, in one place.</p></div><Link href="/upload" className="inline-flex items-center self-start rounded-xl border border-[#dfe4eb] bg-white px-4 py-2.5 text-sm font-semibold shadow-sm"><UploadCloud className="mr-2 h-4 w-4 text-[#23a495]" />Upload lecture</Link></div><div className="grid gap-4 sm:grid-cols-3"><StatCard label="Lectures remembered" value={isLoading?"—":String(lectures.length)} hint={data?.isDemoMode?"includes demo lecture":"across your workspace"} icon={Library} /><StatCard label="Study time" value={isLoading?"—":`${lectures.reduce((s,l)=>s+l.duration,0)}m`} hint="processed audio" icon={Clock3} /><StatCard label="Assignments" value={isLoading?"—":String(data?.counts.assignments ?? 0)} hint="detected from lectures" icon={Check} /></div><div className="grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><section className="rounded-3xl border border-[#e2e6ee] bg-white p-5 shadow-sm sm:p-6"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#23a495]">Recent lectures</p><h2 className="mt-2 text-xl font-semibold tracking-[-.03em]">Keep the thread going</h2></div><Link href="/lectures" className="text-xs font-semibold text-[#23a495]">View all <ChevronRight className="inline h-3 w-3" /></Link></div>{lectures.length===0?<EmptyState title="You haven't uploaded any lectures yet." description="Your first recording will become a searchable study system." />:<div className="mt-5 space-y-2">{lectures.slice(0,4).map(lecture=><LectureRow key={lecture.id} lecture={lecture} />)}</div>}</section><section className="rounded-3xl bg-[#172033] p-6 text-white"><div className="flex items-center justify-between"><div className="icon-tile dark"><Bot className="h-5 w-5" /></div><span className="rounded-full bg-[#23a495]/15 px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.14em] text-[#8ce0d4]">AI assistant</span></div><h2 className="mt-7 text-2xl font-semibold tracking-[-.04em]">What do you want to remember?</h2><p className="mt-3 text-sm leading-6 text-[#aeb8c9]">Ask a question about the demo lecture or open any processed recording.</p><Link href="/lectures/demo-trees-and-graphs?tab=chat" className="mt-7 inline-flex items-center rounded-xl bg-white px-4 py-3 text-sm font-semibold text-[#172033]">Open lecture chat <MessageCircle className="ml-2 h-4 w-4" /></Link></section></div><section><div className="mb-4 flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#23a495]">Workflow</p><h2 className="mt-2 text-xl font-semibold tracking-[-.03em]">From upload to insight</h2></div></div><div className="grid gap-3 md:grid-cols-4">{[[UploadCloud,"Upload","Recording received"],[FileAudio,"Transcribe","Words get timestamps"],[Sparkles,"Understand","AI finds structure"],[Bot,"Ask","Answers stay grounded"]].map(([Icon,title,desc],i)=><div key={title as string} className="flex items-center gap-3 rounded-2xl border border-[#e2e6ee] bg-white p-4 shadow-sm"><span className={`grid h-9 w-9 place-items-center rounded-xl ${i<3?"bg-[#effaf8] text-[#23a495]":"bg-[#fff6e7] text-[#c1842d]"}`}><Icon className="h-4 w-4" /></span><div><p className="text-sm font-semibold">{title as string}</p><p className="mt-0.5 text-[11px] text-[#8b95a7]">{desc as string}</p></div></div>)}</div></section></div> }
function StatCard({label,value,hint,icon:Icon}: any) { return <div className="rounded-3xl border border-[#e2e6ee] bg-white p-5 shadow-sm"><div className="flex items-start justify-between"><p className="text-xs font-semibold text-[#7d879a]">{label}</p><Icon className="h-4 w-4 text-[#23a495]" /></div><p className="mt-5 text-3xl font-semibold tracking-[-.05em]">{value}</p><p className="mt-1 text-xs text-[#9aa3b1]">{hint}</p></div> }
function LectureRow({lecture}: {lecture: LectureRecord}) { return <Link href={`/lectures/${lecture.id}`} className="group flex items-center gap-4 rounded-2xl p-3 transition hover:bg-[#f7f8fb]"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-[#effaf8] text-[#23a495]"><BookOpen className="h-5 w-5" /></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="truncate text-sm font-semibold">{lecture.title}</p>{lecture.isDemo&&<span className="rounded-full bg-[#fff4de] px-2 py-0.5 text-[9px] font-bold uppercase tracking-[.12em] text-[#b77b23]">Demo</span>}</div><p className="mt-1 text-xs text-[#8b95a7]">{lecture.subject} · {lecture.professor} · {lecture.duration} min</p></div><div className="hidden text-right sm:block"><span className="rounded-full bg-[#effaf8] px-2.5 py-1 text-[10px] font-bold text-[#1f887d]">{lecture.status}</span><p className="mt-2 text-[10px] text-[#9aa3b1]">{new Date(lecture.lectureDate).toLocaleDateString()}</p></div><ChevronRight className="h-4 w-4 text-[#bdc4cf] transition group-hover:translate-x-1" /></Link> }

function LecturesPage() { const {data,isLoading}=trpc.lectures.list.useQuery(); const [query,setQuery]=useState(""); const [filter,setFilter]=useState("all"); const lectures=(data?.lectures??[]).filter(l=>(filter==="all"||l.status===filter)&&`${l.title} ${l.subject} ${l.professor}`.toLowerCase().includes(query.toLowerCase())); return <div className="space-y-7"><PageHeader eyebrow="Library" title="My lectures" description="Every recording, organized into something you can actually use." action={<Link href="/upload" className="rounded-xl bg-[#172033] px-4 py-2.5 text-sm font-semibold text-white"><Plus className="mr-1 inline h-4 w-4" />New lecture</Link>} /><div className="flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-[#a0a8b7]" /><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search title, subject, professor" className="w-full rounded-xl border border-[#e1e5ec] bg-white py-2.5 pl-10 pr-3 text-sm outline-none focus:border-[#23a495]" /></div><select value={filter} onChange={e=>setFilter(e.target.value)} className="rounded-xl border border-[#e1e5ec] bg-white px-3 py-2.5 text-sm font-medium outline-none"><option value="all">All statuses</option><option value="completed">Completed</option><option value="processing">Processing</option></select></div>{isLoading?<LoadingState />:<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{lectures.map(lecture=><LectureCard key={lecture.id} lecture={lecture} />)}</div>}{!isLoading&&lectures.length===0&&<EmptyState title="No lectures match that search." description="Try a different title, professor, or status filter." />}</div> }
function LectureCard({lecture}: {lecture: LectureRecord}) { return <div className="group rounded-3xl border border-[#e2e6ee] bg-white p-5 shadow-sm transition hover:-translate-y-1 hover:shadow-md"><div className="flex items-start justify-between"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-[#effaf8] text-[#23a495]"><BookOpen className="h-5 w-5" /></span><button className="rounded-lg p-1.5 text-[#a3adbb] hover:bg-[#f3f5f8]"><MoreHorizontal className="h-4 w-4" /></button></div><div className="mt-6 flex items-center gap-2">{lecture.isDemo&&<span className="rounded-full bg-[#fff4de] px-2 py-0.5 text-[9px] font-bold uppercase tracking-[.12em] text-[#b77b23]">Demo lecture</span>}<span className="rounded-full bg-[#effaf8] px-2 py-0.5 text-[9px] font-bold uppercase tracking-[.12em] text-[#1f887d]">{lecture.status}</span></div><h3 className="mt-3 line-clamp-2 text-lg font-semibold tracking-[-.03em]">{lecture.title}</h3><p className="mt-2 text-xs text-[#8b95a7]">{lecture.subject} · {lecture.professor}</p><div className="mt-5 flex items-center gap-4 border-t border-[#eef1f4] pt-4 text-xs text-[#8b95a7]"><span><Clock3 className="mr-1 inline h-3.5 w-3.5" />{lecture.duration} min</span><span><Sparkles className="mr-1 inline h-3.5 w-3.5" />{lecture.analysis.topics.length} topics</span></div><Link href={`/lectures/${lecture.id}`} className="mt-5 flex items-center justify-between rounded-xl bg-[#f7f8fb] px-3 py-2.5 text-xs font-semibold text-[#172033] group-hover:bg-[#effaf8]">Open lecture <ChevronRight className="h-4 w-4" /></Link></div> }

function LectureDetailPage() { const [, params] = useRoute("/lectures/:id"); const id=params?.id??demoLecture.id; const {data:lecture,isLoading,error}=trpc.lectures.get.useQuery({id}); const [tab,setTab]=useState(new URLSearchParams(window.location.search).get("tab")||"overview"); const [studyOpen,setStudyOpen]=useState(false); const study=trpc.lectures.studyMaterial.useMutation(); if(isLoading)return <LoadingState />; if(error||!lecture)return <EmptyState title="Lecture not found" description="This lecture may have been deleted or is not available in this workspace." />; const tabs=["overview","summary","timeline","transcript","assignments","announcements","chat"]; return <div className="space-y-6"><Link href="/lectures" className="text-xs font-semibold text-[#7d879a] hover:text-[#172033]">← Back to lectures</Link><div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><div className="flex flex-wrap items-center gap-2">{lecture.isDemo&&<span className="rounded-full bg-[#fff4de] px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.14em] text-[#b77b23]">Demo lecture</span>}<span className="rounded-full bg-[#effaf8] px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.14em] text-[#1f887d]">{lecture.status}</span></div><h1 className="mt-3 max-w-3xl text-3xl font-semibold tracking-[-.05em] sm:text-4xl">{lecture.title}</h1><p className="mt-2 text-sm text-[#7d879a]">{lecture.subject} · {lecture.professor} · {new Date(lecture.lectureDate).toLocaleDateString()} · {lecture.duration} min</p></div><button onClick={()=>{setTab("chat");window.scrollTo({top:0,behavior:"smooth"})}} className="rounded-xl bg-[#172033] px-4 py-3 text-sm font-semibold text-white"><MessageCircle className="mr-2 inline h-4 w-4" />Ask LectureAI</button></div><div className="overflow-x-auto border-b border-[#e1e5ec]"><div className="flex min-w-max gap-6">{tabs.map(x=><button key={x} onClick={()=>setTab(x)} className={`border-b-2 px-1 pb-3 text-xs font-semibold capitalize ${tab===x?"border-[#23a495] text-[#23a495]":"border-transparent text-[#8b95a7] hover:text-[#172033]"}`}>{x}</button>)}</div></div>{tab==="overview"&&<OverviewTab lecture={lecture} onStudy={()=>{setStudyOpen(true);study.mutate({lectureId:lecture.id})}} studyPending={study.isPending} />}{tab==="summary"&&<SummaryTab lecture={lecture} />}{tab==="timeline"&&<TimelineTab lecture={lecture} />}{tab==="transcript"&&<TranscriptTab lecture={lecture} />}{tab==="assignments"&&<AssignmentsTab lecture={lecture} />}{tab==="announcements"&&<AnnouncementsTab lecture={lecture} />}{tab==="chat"&&<ChatTab lecture={lecture} />}{studyOpen&&<StudyModal loading={study.isPending} markdown={study.data?.markdown??""} error={study.error?.message} onClose={()=>setStudyOpen(false)} />}</div> }
function OverviewTab({lecture,onStudy,studyPending}: {lecture:LectureRecord;onStudy:()=>void;studyPending:boolean}) { return <div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><div className="space-y-5"><div className="rounded-3xl border border-[#e2e6ee] bg-white p-6 shadow-sm"><div className="flex items-center justify-between"><div><SectionEyebrow>Lecture summary</SectionEyebrow><h2 className="mt-2 text-xl font-semibold tracking-[-.03em]">The big picture</h2></div><button onClick={onStudy} className="rounded-xl border border-[#dfe4eb] px-3 py-2 text-xs font-semibold"><Sparkles className="mr-1 inline h-3.5 w-3.5 text-[#23a495]" />{studyPending?"Generating…":"Generate study material"}</button></div><p className="mt-5 max-w-3xl text-sm leading-7 text-[#677187]">{lecture.analysis.summary}</p></div><TimelineTab lecture={lecture} compact /></div><div className="space-y-5"><div className="rounded-3xl bg-[#172033] p-6 text-white"><SectionEyebrow light>Key concepts</SectionEyebrow><div className="mt-5 space-y-3">{lecture.analysis.keyConcepts.map((x,i)=><div key={x} className="flex gap-3 text-sm leading-6 text-[#dce3ec]"><span className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-[#7be0d2]" />{x}</div>)}</div></div><div className="rounded-3xl border border-[#e2e6ee] bg-white p-6 shadow-sm"><SectionEyebrow>At a glance</SectionEyebrow><div className="mt-5 grid grid-cols-2 gap-3">{[["Topics",lecture.analysis.topics.length],["Assignments",lecture.analysis.assignments.length],["Questions",lecture.analysis.questions.length],["Announcements",lecture.analysis.announcements.length]].map(([label,value])=><div key={label as string} className="rounded-2xl bg-[#f7f8fb] p-4"><p className="text-xl font-semibold">{value as number}</p><p className="mt-1 text-xs text-[#8b95a7]">{label as string}</p></div>)}</div></div></div></div> }
function SummaryTab({lecture}: {lecture:LectureRecord}) { return <div className="grid gap-5 lg:grid-cols-2"><TextCard title="Summary" eyebrow="AI-generated overview"><p className="text-sm leading-7 text-[#677187]">{lecture.analysis.summary}</p></TextCard><TextCard title="Important points" eyebrow="Revision ready"><BulletList items={lecture.analysis.importantPoints} /></TextCard><TextCard title="Topics discussed" eyebrow="What the lecture covered"><div className="flex flex-wrap gap-2">{lecture.analysis.topics.map(x=><span key={x} className="rounded-full bg-[#effaf8] px-3 py-2 text-xs font-semibold text-[#227e75]">{x}</span>)}</div></TextCard><TextCard title="Questions raised" eyebrow="Good study prompts"><BulletList items={lecture.analysis.questions} /></TextCard></div> }
function TimelineTab({lecture,compact=false}: {lecture:LectureRecord;compact?:boolean}) { return <div className={`rounded-3xl border border-[#e2e6ee] bg-white p-6 shadow-sm ${compact?"":"max-w-4xl"}`}><SectionEyebrow>Timeline</SectionEyebrow><h2 className="mt-2 text-xl font-semibold tracking-[-.03em]">Follow the lecture arc</h2><div className="relative mt-7 space-y-5 pl-8 before:absolute before:bottom-2 before:left-[11px] before:top-2 before:w-px before:bg-[#dfe8e6]">{lecture.timeline.map((event)=><button key={event.timestamp} onClick={()=>document.getElementById(`segment-${event.timestamp}`)?.scrollIntoView({behavior:"smooth",block:"center"})} className="group relative block w-full text-left"><span className="absolute -left-8 top-1.5 h-2.5 w-2.5 rounded-full border-2 border-white bg-[#23a495] ring-4 ring-[#effaf8]" /><div className="flex items-start justify-between gap-4"><div><p className="text-sm font-semibold group-hover:text-[#23a495]">{event.label}</p><p className="mt-1 text-xs leading-5 text-[#8b95a7]">{event.description}</p></div><span className="shrink-0 rounded-lg bg-[#f7f8fb] px-2 py-1 text-[10px] font-bold text-[#7d879a]">{formatTimestamp(event.timestamp)}</span></div></button>)}</div></div> }
function TranscriptTab({lecture}: {lecture:LectureRecord}) { const [query,setQuery]=useState(""); const segments=lecture.transcript.filter(s=>s.text.toLowerCase().includes(query.toLowerCase())); return <div className="rounded-3xl border border-[#e2e6ee] bg-white p-6 shadow-sm"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><SectionEyebrow>Transcript</SectionEyebrow><h2 className="mt-2 text-xl font-semibold tracking-[-.03em]">Search every word</h2></div><div className="relative sm:w-64"><Search className="absolute left-3 top-2.5 h-4 w-4 text-[#a0a8b7]" /><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Find in transcript" className="w-full rounded-xl border border-[#e1e5ec] py-2 pl-9 pr-3 text-xs outline-none focus:border-[#23a495]" /></div></div><div className="mt-6 space-y-1">{segments.map(segment=><div id={`segment-${segment.startTime}`} key={segment.id} className="group flex gap-4 rounded-2xl p-4 hover:bg-[#f7f8fb]"><span className="w-12 shrink-0 pt-0.5 text-[11px] font-bold text-[#23a495]">{formatTimestamp(segment.startTime)}</span><div><p className="text-[11px] font-semibold text-[#8b95a7]">{segment.speaker}</p><p className="mt-1 text-sm leading-6 text-[#59657a]">{segment.text}</p></div></div>)}</div></div> }
function AssignmentsTab({lecture}: {lecture:LectureRecord}) { return <div className="space-y-4">{lecture.analysis.assignments.length?lecture.analysis.assignments.map(item=><div key={item.description} className="rounded-3xl border border-[#e2e6ee] bg-white p-6 shadow-sm"><div className="flex gap-4"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-2xl bg-[#fff4de] text-[#bd812b]"><Check className="h-5 w-5" /></span><div><SectionEyebrow>Assignment · {formatTimestamp(item.timestamp)}</SectionEyebrow><p className="mt-2 text-base font-semibold">{item.description}</p><p className="mt-3 text-xs text-[#8b95a7]">{item.deadline?`Deadline: ${item.deadline}`:"Deadline not mentioned."}</p></div></div></div>):<EmptyState title="No assignments detected." description="Nothing was explicitly identified in this lecture." />}</div> }
function AnnouncementsTab({lecture}: {lecture:LectureRecord}) { return <div className="space-y-4">{lecture.analysis.announcements.length?lecture.analysis.announcements.map(item=><div key={item.description} className="rounded-3xl border border-[#e2e6ee] bg-white p-6 shadow-sm"><div className="flex gap-4"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-2xl bg-[#e8e0fb] text-[#8062b7]"><CalendarDays className="h-5 w-5" /></span><div><SectionEyebrow>Announcement · {formatTimestamp(item.timestamp)}</SectionEyebrow><p className="mt-2 text-base font-semibold">{item.description}</p><p className="mt-3 text-xs text-[#8b95a7]">Source: {lecture.title} at {formatTimestamp(item.timestamp)}</p></div></div></div>):<EmptyState title="No announcements detected." description="Nothing was explicitly identified in this lecture." />}</div> }
function ChatTab({lecture}: {lecture:LectureRecord}) { return <div className="grid gap-5 lg:grid-cols-[.65fr_1.35fr]"><div className="rounded-3xl bg-[#172033] p-6 text-white"><SectionEyebrow light>Lecture context</SectionEyebrow><h2 className="mt-3 text-2xl font-semibold tracking-[-.04em]">Ask about this lecture.</h2><p className="mt-3 text-sm leading-6 text-[#aeb8c9]">Answers are grounded in the selected lecture and include sources when available.</p><div className="mt-8 space-y-2">{["Summarize this lecture","What homework was given?","Explain the hardest concept","What should I study for the exam?"].map(q=><span key={q} className="block rounded-xl border border-white/10 bg-white/[.05] px-3 py-2.5 text-xs text-[#dce3ec]">{q}</span>)}</div></div><ChatBox lecture={lecture} /></div> }
function ChatBox({lecture}: {lecture:LectureRecord}) { const [question,setQuestion]=useState(""); const [messages,setMessages]=useState<Array<{role:"user"|"assistant";content:string;source?:number|null}>>([{role:"assistant",content:"What would you like to know about this lecture? I’ll keep the answer grounded in the transcript."}]); const chat=trpc.lectures.chat.useMutation({onSuccess:(data)=>setMessages(m=>[...m,{role:"assistant",content:data.answer,source:data.source}]),onError:(e)=>toast.error(e.message)}); const send=()=>{if(!question.trim()||chat.isPending)return; const q=question.trim();setMessages(m=>[...m,{role:"user",content:q}]);setQuestion("");chat.mutate({lectureId:lecture.id,question:q})}; return <div className="flex min-h-[560px] flex-col rounded-3xl border border-[#e2e6ee] bg-white shadow-sm"><div className="border-b border-[#edf0f4] p-5"><SectionEyebrow>LectureAI</SectionEyebrow><p className="mt-2 text-sm font-semibold">{lecture.title}</p></div><div className="flex-1 space-y-5 p-5">{messages.map((m,i)=><div key={i} className={`flex gap-3 ${m.role==="user"?"justify-end":""}`}><span className={`grid h-8 w-8 shrink-0 place-items-center rounded-xl ${m.role==="assistant"?"bg-[#effaf8] text-[#23a495]":"bg-[#e8e0fb] text-[#8062b7]"}`}>{m.role==="assistant"?<Bot className="h-4 w-4" />:<span className="text-[10px] font-bold">You</span>}</span><div className={`max-w-[80%] rounded-2xl px-4 py-3 text-sm leading-6 ${m.role==="assistant"?"bg-[#f7f8fb] text-[#59657a]":"bg-[#172033] text-white"}`}><Streamdown>{m.content}</Streamdown>{m.source!=null&&<p className="mt-2 text-[10px] font-semibold text-[#23a495]">Source · {formatTimestamp(m.source)}</p>}</div></div>)}{chat.isPending&&<div className="flex items-center gap-2 text-xs text-[#8b95a7]"><span className="typing-dot" /><span className="typing-dot" /><span className="typing-dot" /> LectureAI is thinking from the transcript…</div>}</div><div className="border-t border-[#edf0f4] p-4"><div className="flex items-end gap-2 rounded-2xl border border-[#dfe4eb] bg-[#fdfefe] p-2 focus-within:border-[#23a495]"><textarea value={question} onChange={e=>setQuestion(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();send()}}} placeholder="Ask about this lecture…" rows={2} className="min-h-[44px] flex-1 resize-none border-0 bg-transparent px-2 py-1 text-sm outline-none" /><button onClick={send} className="rounded-xl bg-[#23a495] p-2.5 text-white disabled:opacity-50" disabled={!question.trim()||chat.isPending}><ArrowUpRight className="h-4 w-4" /></button></div><div className="mt-2 flex items-center justify-between px-1 text-[10px] text-[#a0a8b7]"><span>Enter to send · Shift + Enter for a new line</span><button onClick={()=>setMessages([{role:"assistant",content:"Conversation cleared. What would you like to know?"}])} className="font-semibold hover:text-[#172033]">Clear</button></div></div></div> }

function UploadPage() { const {isAuthenticated}=useAuth(); const [file,setFile]=useState<File|null>(null); const [title,setTitle]=useState(""); const [subject,setSubject]=useState(""); const [professor,setProfessor]=useState(""); const [date,setDate]=useState(new Date().toISOString().slice(0,10)); const upload=trpc.lectures.upload.useMutation({onSuccess:(data)=>{toast.success("Lecture processed and added to your memory.");window.location.assign(`/lectures/${data.lecture.id}`)},onError:(e)=>toast.error(e.message)}); const submit=async()=>{if(!isAuthenticated){startLogin();return}if(!file||!title.trim()){toast.error("Add a title and select an audio or video file.");return}const buffer=await file.arrayBuffer();const bytes=new Uint8Array(buffer);let binary="";bytes.forEach(b=>binary+=String.fromCharCode(b));upload.mutate({title,subject,professor,lectureDate:date,filename:file.name,mimeType:file.type,fileData:btoa(binary)})}; return <div className="mx-auto max-w-3xl space-y-7"><PageHeader eyebrow="Build your memory" title="Upload a lecture" description="Give LectureAI a recording and it will create a searchable study system." /><div className="rounded-3xl border border-[#e2e6ee] bg-white p-6 shadow-sm sm:p-8"><div className="grid gap-4 sm:grid-cols-2"><Field label="Lecture title" value={title} onChange={setTitle} placeholder="e.g. Trees & Graphs" /><Field label="Subject (optional)" value={subject} onChange={setSubject} placeholder="e.g. Data Structures" /><Field label="Professor (optional)" value={professor} onChange={setProfessor} placeholder="e.g. Dr. Maya Chen" /><Field label="Lecture date" value={date} onChange={setDate} type="date" /></div><label className="mt-5 block"><span className="mb-2 block text-xs font-semibold text-[#677187]">Recording</span><input type="file" accept="audio/*,video/mp4" className="hidden" onChange={e=>setFile(e.target.files?.[0]??null)} id="lecture-file" /><span className="flex min-h-44 cursor-pointer flex-col items-center justify-center rounded-2xl border-2 border-dashed border-[#d7e7e4] bg-[#f8fcfb] px-6 text-center transition hover:border-[#23a495]" onClick={()=>document.getElementById("lecture-file")?.click()}><span className="grid h-12 w-12 place-items-center rounded-2xl bg-[#effaf8] text-[#23a495]"><UploadCloud className="h-6 w-6" /></span><span className="mt-4 text-sm font-semibold text-[#172033]">{file?file.name:"Drop a recording here or browse"}</span><span className="mt-2 text-xs text-[#8b95a7]">MP3, WAV, M4A, WEBM, OGG, or MP4 · max 16MB for the prototype</span></span></label><div className="mt-6 grid gap-2 sm:grid-cols-4">{[[UploadCloud,"Upload"],[FileAudio,"Transcribe"],[Sparkles,"Understand"],[Check,"Ready"]].map(([Icon,label],i)=><div key={label as string} className={`rounded-xl p-3 text-center ${upload.isPending&&i<3?"bg-[#effaf8]":"bg-[#f7f8fb]"}`}><Icon className={`mx-auto h-4 w-4 ${upload.isPending&&i<3?"text-[#23a495]":"text-[#a0a8b7]"}`} /><p className="mt-2 text-[10px] font-semibold text-[#7d879a]">{label as string}</p></div>)}</div><button onClick={submit} disabled={upload.isPending} className="mt-7 w-full rounded-xl bg-[#172033] px-4 py-3.5 text-sm font-semibold text-white disabled:opacity-50">{upload.isPending?"LectureAI is processing…":isAuthenticated?"Process lecture":"Sign in to process a lecture"}</button>{!isAuthenticated&&<p className="mt-3 text-center text-xs text-[#8b95a7]">You can explore the marked demo lecture without signing in.</p>}</div></div> }
function Field({label,value,onChange,placeholder,type="text"}: any) { return <label><span className="mb-2 block text-xs font-semibold text-[#677187]">{label}</span><input type={type} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} className="w-full rounded-xl border border-[#e1e5ec] bg-white px-3 py-2.5 text-sm outline-none focus:border-[#23a495]" /></label> }

function SearchPage() { const [query,setQuery]=useState(""); const search=trpc.lectures.search.useQuery({query},{enabled:query.trim().length>1}); return <div className="space-y-7"><PageHeader eyebrow="Global search" title="Search your memory" description="Find the exact lecture moment where a concept, assignment, or announcement appeared." /><div className="relative max-w-2xl"><Search className="absolute left-4 top-3.5 h-5 w-5 text-[#a0a8b7]" /><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Try “AVL”, “homework”, or “deletion”" className="w-full rounded-2xl border border-[#dfe4eb] bg-white py-3.5 pl-12 pr-4 text-sm shadow-sm outline-none focus:border-[#23a495]" /></div>{!query?<div className="rounded-3xl border border-dashed border-[#d6dce5] bg-white p-10 text-center"><Search className="mx-auto h-7 w-7 text-[#23a495]" /><h2 className="mt-4 font-semibold">Search across every processed lecture.</h2><p className="mt-2 text-sm text-[#8b95a7]">Try a topic from the demo lecture to see timestamped matches.</p></div>:search.isLoading?<LoadingState />:search.data?.length?<div className="max-w-3xl space-y-3">{search.data.map((result,i)=><Link key={`${result.lectureId}-${i}`} href={`/lectures/${result.lectureId}?tab=transcript`} className="block rounded-2xl border border-[#e2e6ee] bg-white p-5 shadow-sm transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex items-center justify-between gap-4"><p className="text-sm font-semibold">{result.lectureTitle}</p><span className="rounded-lg bg-[#effaf8] px-2 py-1 text-[10px] font-bold text-[#227e75]">{formatTimestamp(result.timestamp)}</span></div><p className="mt-3 text-sm leading-6 text-[#677187]">{result.context}</p><p className="mt-3 text-xs font-semibold text-[#23a495]">Open transcript section <ChevronRight className="inline h-3 w-3" /></p></Link>)}</div>:<EmptyState title={`No results for “${query}”.`} description="Try a broader topic or open the demo lecture to explore the structure." />}</div> }
function AssignmentsPage() { const {data}=trpc.lectures.list.useQuery(); const assignments=(data?.lectures??[]).flatMap(l=>l.analysis.assignments.map(a=>({...a,lecture:l}))); return <div className="space-y-7"><PageHeader eyebrow="Stay on track" title="Assignments" description="Homework detected across your lectures, with the source moment attached." /><div className="max-w-3xl space-y-3">{assignments.map(item=><Link key={`${item.lecture.id}-${item.description}`} href={`/lectures/${item.lecture.id}?tab=assignments`} className="flex gap-4 rounded-3xl border border-[#e2e6ee] bg-white p-5 shadow-sm transition hover:-translate-y-0.5 hover:shadow-md"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-2xl bg-[#fff4de] text-[#bd812b]"><Check className="h-5 w-5" /></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-semibold">{item.description}</p>{item.lecture.isDemo&&<span className="rounded-full bg-[#fff4de] px-2 py-0.5 text-[9px] font-bold uppercase tracking-[.12em] text-[#b77b23]">Demo</span>}</div><p className="mt-2 text-xs text-[#8b95a7]">{item.lecture.title} · {formatTimestamp(item.timestamp)} · {item.deadline?`Deadline ${item.deadline}`:"Deadline not mentioned."}</p></div><ChevronRight className="mt-1 h-4 w-4 shrink-0 text-[#bdc4cf]" /></Link>)}{!assignments.length&&<EmptyState title="No assignments yet." description="Assignments will appear here when LectureAI detects them in a processed lecture." />}</div></div> }
function SettingsPage() { const {user,logout,isAuthenticated}=useAuth(); return <div className="space-y-7"><PageHeader eyebrow="Workspace preferences" title="Settings" description="Keep your profile and account controls in one simple place." /><div className="max-w-2xl space-y-4"><div className="rounded-3xl border border-[#e2e6ee] bg-white p-6 shadow-sm"><SectionEyebrow>Profile</SectionEyebrow><div className="mt-5 flex items-center gap-4"><span className="avatar large bg-[#d7c8f5]">{user?.name?.slice(0,2).toUpperCase()??"AR"}</span><div><p className="font-semibold">{user?.name??"Demo Explorer"}</p><p className="mt-1 text-sm text-[#8b95a7]">{user?.email??"Sign in to connect your account"}</p></div></div><div className="mt-6 rounded-2xl bg-[#effaf8] p-4 text-xs leading-6 text-[#277b73]">LectureAI keeps the assistant grounded in the selected lecture. Your private uploads are scoped to your account when you sign in.</div></div><div className="rounded-3xl border border-[#e2e6ee] bg-white p-6 shadow-sm"><SectionEyebrow>Account</SectionEyebrow><div className="mt-5 flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><p className="text-sm font-semibold">{isAuthenticated?"Sign out of LectureAI":"Demo mode is active"}</p><p className="mt-1 text-xs text-[#8b95a7]">{isAuthenticated?"End this session on the current device.":"Explore the sample lecture, then sign in to upload your own."}</p></div>{isAuthenticated?<button onClick={()=>logout()} className="rounded-xl border border-[#e1e5ec] px-3 py-2 text-xs font-semibold hover:bg-[#fff1f0]">Log out</button>:<button onClick={()=>startLogin()} className="rounded-xl bg-[#172033] px-3 py-2 text-xs font-semibold text-white">Sign in</button>}</div></div></div></div> }
function AuthPage() {
  const [location] = useLocation();
  const isRegister = location === "/register";
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [submitted, setSubmitted] = useState(false);
  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    if (isRegister && (!name.trim() || !email.trim())) return;
    if (isRegister) sessionStorage.setItem("lectureai-registration-profile", JSON.stringify({ name: name.trim(), email: email.trim() }));
    setSubmitted(true);
    startLogin();
  };
  return <div className="grid min-h-screen place-items-center bg-[#f7f8fb] p-5"><div className="w-full max-w-md rounded-3xl border border-[#e2e6ee] bg-white p-7 shadow-xl shadow-[#172033]/5"><Brand light /><div className="mx-auto mt-10 grid h-14 w-14 place-items-center rounded-2xl bg-[#effaf8] text-[#23a495]"><GraduationCap className="h-7 w-7" /></div><h1 className="mt-6 text-center text-2xl font-semibold tracking-[-.04em]">{isRegister ? "Create your academic memory" : "Welcome back to LectureAI"}</h1><p className="mt-3 text-center text-sm leading-6 text-[#7d879a]">{isRegister ? "Start with a clean workspace. Your activity stays at zero until you upload or process a lecture." : "Sign in to continue with your private lecture workspace."}</p><form onSubmit={submit} className="mt-7 space-y-4">{isRegister&&<Field label="Your name" value={name} onChange={setName} placeholder="e.g. Ananya Rao" />}<Field label="Email address" value={email} onChange={setEmail} placeholder="you@example.com" type="email" />{isRegister&&<p className="text-[11px] leading-5 text-[#8b95a7]">Account security is handled by Manus OAuth. We only use your name and email to initialize your personal workspace.</p>}<button type="submit" disabled={submitted} className="w-full rounded-xl bg-[#172033] px-4 py-3.5 text-sm font-semibold text-white disabled:opacity-60">{submitted ? "Opening secure sign in…" : isRegister ? "Create account" : "Sign in"} <ArrowUpRight className="ml-2 inline h-4 w-4" /></button></form><div className="mt-6 border-t border-[#edf0f4] pt-5 text-center text-xs text-[#8b95a7]">{isRegister ? <>Already have an account? <Link href="/login" className="font-semibold text-[#23a495]">Sign in</Link></> : <>New to LectureAI? <Link href="/register" className="font-semibold text-[#23a495]">Create an account</Link></>}</div><Link href="/" className="mt-4 block text-center text-xs font-semibold text-[#23a495]">Back to home</Link></div></div>;
}
function PageHeader({eyebrow,title,description,action}: any) { return <div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><SectionEyebrow>{eyebrow}</SectionEyebrow><h1 className="mt-2 text-3xl font-semibold tracking-[-.05em] sm:text-4xl">{title}</h1><p className="mt-2 text-sm text-[#7d879a]">{description}</p></div>{action}</div> }
function TextCard({title,eyebrow,children}: any) { return <div className="rounded-3xl border border-[#e2e6ee] bg-white p-6 shadow-sm"><SectionEyebrow>{eyebrow}</SectionEyebrow><h2 className="mt-2 text-xl font-semibold tracking-[-.03em]">{title}</h2><div className="mt-5">{children}</div></div> }
function BulletList({items}: {items:string[]}) { return <div className="space-y-3">{items.map(item=><div key={item} className="flex gap-3 text-sm leading-6 text-[#677187]"><span className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-[#23a495]" />{item}</div>)}</div> }
function EmptyState({title,description}: {title:string;description:string}) { return <div className="rounded-3xl border border-dashed border-[#d6dce5] bg-white p-10 text-center"><FileText className="mx-auto h-7 w-7 text-[#23a495]" /><h2 className="mt-4 font-semibold">{title}</h2><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-[#8b95a7]">{description}</p></div> }
function LoadingState() { return <div className="rounded-3xl border border-[#e2e6ee] bg-white p-12 text-center shadow-sm"><div className="mx-auto h-8 w-8 animate-spin rounded-full border-2 border-[#d8efeb] border-t-[#23a495]" /><p className="mt-4 text-sm text-[#8b95a7]">Loading your academic memory…</p></div> }
function StudyModal({loading,markdown,error,onClose}: {loading:boolean;markdown:string;error?:string;onClose:()=>void}) { return <div className="fixed inset-0 z-50 grid place-items-center bg-[#172033]/40 p-5"><div className="max-h-[85vh] w-full max-w-2xl overflow-auto rounded-3xl bg-white p-6 shadow-2xl"><div className="flex items-start justify-between"><div><SectionEyebrow>Study mode</SectionEyebrow><h2 className="mt-2 text-2xl font-semibold">Your revision kit</h2></div><button onClick={onClose} className="rounded-xl p-2 hover:bg-[#f3f5f8]"><X className="h-5 w-5" /></button></div>{loading?<div className="py-16 text-center"><Sparkles className="mx-auto h-8 w-8 animate-pulse text-[#23a495]" /><p className="mt-4 text-sm text-[#8b95a7]">Generating only from this lecture…</p></div>:error?<div className="mt-6 rounded-2xl bg-[#fff1f0] p-4 text-sm text-[#b4514a]">{error}</div>:<div className="prose prose-sm mt-6 max-w-none text-[#59657a]"><Streamdown>{markdown||"No study material returned."}</Streamdown></div>}</div></div> }

export default App;
